-- Ejecutar una vez en SQL Editor de un proyecto Supabase nuevo.
create extension if not exists pgcrypto with schema extensions;
create table public.spaces(id uuid primary key default gen_random_uuid(), owner uuid not null references auth.users(id));
create table public.members(space_id uuid not null references public.spaces(id), user_id uuid primary key references auth.users(id), name text not null, approved boolean not null default false);
create table public.invites(code text primary key, space_id uuid not null references public.spaces(id), expires timestamptz not null);
create table public.items(id uuid primary key, space_id uuid not null references public.spaces(id), kind text not null check(kind in ('plan','compra','viaje','nota','idea','recuerdo','meta','latido')), title text not null, detail text not null default '', day text not null default '', done boolean not null default false, deleted boolean not null default false, author text not null, updated_at timestamptz not null default now());
alter table public.spaces enable row level security;
alter table public.members enable row level security;
alter table public.invites enable row level security;
alter table public.items enable row level security;
create function public.can_access(s uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from members where user_id=auth.uid() and space_id=s and approved) $$;
create policy item_read on public.items for select to authenticated using (public.can_access(space_id));
create policy item_insert on public.items for insert to authenticated with check (public.can_access(space_id));
create policy item_update on public.items for update to authenticated using (public.can_access(space_id)) with check (public.can_access(space_id));
create function public.create_space(display text) returns uuid language plpgsql security definer set search_path=public as $$ declare s uuid; begin if auth.uid() is null then raise exception 'Inicia sesión'; end if; insert into spaces(owner) values(auth.uid()) returning id into s; insert into members values(s,auth.uid(),left(display,80),true); return s; end $$;
create function public.make_invite() returns text language plpgsql security definer set search_path=public,extensions as $$ declare s uuid; c text; begin select id into s from spaces where owner=auth.uid() for update; if s is null then raise exception 'Solo el creador puede invitar'; end if; if (select count(*) from members where space_id=s)>=2 then raise exception 'Espacio completo'; end if; delete from invites where space_id=s; c:=upper(encode(extensions.gen_random_bytes(8),'hex')); insert into invites values(c,s,now()+interval '30 minutes'); return c; end $$;
create function public.join_space(invite_code text,display text) returns uuid language plpgsql security definer set search_path=public as $$ declare s uuid; begin if auth.uid() is null then raise exception 'Inicia sesión'; end if; select space_id into s from invites where code=upper(trim(invite_code)) and expires>now() for update; if s is null then raise exception 'Código inválido o vencido'; end if; perform 1 from spaces where id=s for update; if (select count(*) from members where space_id=s)>=2 then raise exception 'Espacio completo'; end if; insert into members values(s,auth.uid(),left(display,80),false); delete from invites where code=upper(trim(invite_code)); return s; end $$;
create function public.approve_member(member_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin update members set approved=true where user_id=member_id and space_id in(select id from spaces where owner=auth.uid()); if not found then raise exception 'Solicitud no encontrada'; end if; end $$;
create function public.my_space() returns jsonb language sql stable security definer set search_path=public as $$ select jsonb_build_object('id',m.space_id,'approved',m.approved,'name',m.name,'owner',s.owner=auth.uid(),'members',(select coalesce(jsonb_agg(jsonb_build_object('id',x.user_id,'name',x.name,'approved',x.approved)),'[]'::jsonb) from members x where x.space_id=m.space_id and (m.approved or x.user_id=auth.uid()))) from members m join spaces s on s.id=m.space_id where m.user_id=auth.uid() $$;
revoke execute on function public.can_access(uuid),public.create_space(text),public.make_invite(),public.join_space(text,text),public.approve_member(uuid),public.my_space() from public,anon;
grant execute on function public.can_access(uuid),public.create_space(text),public.make_invite(),public.join_space(text,text),public.approve_member(uuid),public.my_space() to authenticated;
grant select,insert,update on public.items to authenticated;
alter publication supabase_realtime add table public.items;